{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Fentanyl, the closest-scoring analogue, has an absolute oral bioavailability of 0.31 (31%) after swallowed oral administration in healthy subjects, supporting F >= 20% for this tertiary-amide/basic-amine opioid-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ebastine, a lipophilic basic drug containing diphenyl and piperidine motifs, achieves about 40% oral bioavailability in humans, supporting a high prediction for the similarly lipophilic diphenyl-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Doxapram, which shares a pyrrolidine/pyrrolidinone and diphenyl framework, shows about 61% systemic availability after oral administration, supporting moderate-to-good oral absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Loperamide has very low absolute oral bioavailability (0.3%) attributed to P-gp efflux and poor solubility, but its chlorophenyl-piperidine and extreme P-gp liability are not mirrored in the query's 3-hydroxypyrrolidine amide, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Phenoperidine shows low systemic bioavailability (9.9%) after oral administration, but its carbamate-ester moiety is more susceptible to first-pass hydrolysis than the query's amide, making this low-F evidence less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the most transferable experimental evidence—fentanyl (32%), ebastine (~40%), doxapram (~60%), and fexofenadine (~30-41%)—supports moderate oral bioavailability for this lipophilic tertiary-amide/pyrrolidinol scaffold. The low-F analogues (loperamide, terfenadine, phenoperidine) are less transferable due to specific P-gp/solubility, extreme CYP metabolism, or ester lability not mirrored in the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule; all evidence comes from analogues with low Morgan similarity (<0.33).",
    "Unknown whether the query is a P-gp or CYP3A4 substrate, which could substantially alter oral bioavailability.",
    "Some supporting records report systemic availability rather than strict absolute bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

